rule_text:
SKIPCHECK;


[ {'Local (System)'} , 'Actual'] = N:
  IF ( ELISANC ( 'Flow Code', 'TOTACTIVITIES', !Flow Code) = 1 & !BS Account @<> '55000099',
  ['Local'], STET);

[ {'USD (System)'}  , 'Actual'] = N:
  IF ( ELISANC ( 'Flow Code', 'TOTACTIVITIES', !Flow Code) = 1 & !BS Account @<> '55000099',
  ['USD'], STET);


['USD', '55000099', 'F16' , 'Actual']= N:

  ['All BS Account', 'TOTACTIVITIES', 'USD (System)'] *-1;

['Local', '55000099', 'F16' , 'Actual'] = N:

  ['All BS Account', 'TOTACTIVITIES', 'Local (System)'] *-1;

['F00', '55000099' , 'Actual'] = N:

  IF ( SUBST( !Fiscal Period, 5,3)@= '001', stet,
  DB('Balance Sheet', !Scenario, 
      ATTRS ( 'Fiscal Period', !Fiscal Period, 'Prior Period'), 
     !Company, !Profit Center, !Trading Partner, !BS Account, 'F99', !Balance Sheet Source ,!mBalance Sheet ));


['F00' , 'Actual'] = N:
  DB('Balance Sheet', !Scenario, 
      ATTRS ( 'Fiscal Period', !Fiscal Period, 'Prior Period'), 
     !Company, !Profit Center, !Trading Partner, !BS Account, 'F99', !Balance Sheet Source ,!mBalance Sheet );

#----- Outlook & Plan
[{'Outlook', 'Plan'}] = N:
  IF ( ELISANC ( 'Fiscal Period', 'Outlook Periods', !Fiscal Period) = 1 , CONTINUE, STET );

[ {'Local (System)'} , {'Outlook', 'Plan'}] = N:
  IF ( ELISANC ( 'Flow Code', 'TOTACTIVITIES', !Flow Code) = 1 & !BS Account @<> '55000099',
  ['Local'], STET);

[ {'USD (System)'}  , {'Outlook', 'Plan'}] = N:
  IF ( ELISANC ( 'Flow Code', 'TOTACTIVITIES', !Flow Code) = 1 & !BS Account @<> '55000099',
  ['USD'], STET);


['USD', '55000099', 'F16' , {'Outlook', 'Plan'}] = N:

  ['All BS Account', 'TOTACTIVITIES', 'USD (System)'] *-1;

['Local', '55000099', 'F16' , {'Outlook', 'Plan'}] = N:

  ['All BS Account', 'TOTACTIVITIES', 'Local (System)'] *-1;


['F00', '55000099' , {'Outlook', 'Plan'}] = N:

    IF ( SUBST( !Fiscal Period, 5,3)@= '001', stet,
  DB('Balance Sheet', !Scenario, 
      ATTRS ( 'Fiscal Period', !Fiscal Period, 'Prior Period'), 
     !Company, !Profit Center, !Trading Partner, !BS Account, 'F99', !Balance Sheet Source ,!mBalance Sheet ));



['F00' , {'Outlook', 'Plan'}] = N:
  DB('Balance Sheet', !Scenario, 
      ATTRS ( 'Fiscal Period', !Fiscal Period, 'Prior Period'), 
     !Company, !Profit Center, !Trading Partner, !BS Account, 'F99', !Balance Sheet Source ,!mBalance Sheet );

#-----


['F00'] = C:
  IF ( ELLEV ('Fiscal Period', !Fiscal Period) <> 0,

    DB('Balance Sheet', !Scenario, 
      ELCOMP ( 'Fiscal Period', !Fiscal Period, 1), 
      !Company, !Profit Center, !Trading Partner, !BS Account, 'F00', !Balance Sheet Source ,!mBalance Sheet ),

  STET );

['F99'] = C:

  IF ( ELLEV ('Fiscal Period', !Fiscal Period) <> 0,

    DB('Balance Sheet', !Scenario, 
      ELCOMP ( 'Fiscal Period', !Fiscal Period, ELCOMPN ( 'Fiscal Period', !Fiscal Period )), 
     !Company, !Profit Center, !Trading Partner, !BS Account, 'F99', !Balance Sheet Source ,!mBalance Sheet ),

  STET );




FEEDERS;

#--- Actual
['F99' , 'Actual'] =>   DB('Balance Sheet', !Scenario, 
      ATTRS ( 'Fiscal Period', !Fiscal Period, 'Next Period'), 
    !Company,  !Profit Center, !Trading Partner, !BS Account, 'F00', !Balance Sheet Source ,!mBalance Sheet );


['USD', 'TOTACTIVITIES' , 'Actual'] => [ 'USD (System)' ] ;
['Local', 'TOTACTIVITIES' , 'Actual']=> [ 'Local (System)' ] ;

['All BS Account', 'TOTACTIVITIES', 'USD (System)' , 'Actual'] => ['USD', '55000099', 'F16'];
['All BS Account', 'TOTACTIVITIES', 'Local (System)' , 'Actual'] => ['Local', '55000099', 'F16'];


#----- Outlook & Plan
['F99' , 'Outlook', 'Current Close Period'] =>   DB('Balance Sheet', !Scenario, 
      ATTRS ( 'Fiscal Period', !Fiscal Period, 'Next Period'), 
    !Company,  !Profit Center, !Trading Partner, !BS Account, 'F00', !Balance Sheet Source ,!mBalance Sheet );

['F99' , 'Plan', 'Current Close Period'] =>   DB('Balance Sheet', !Scenario, 
      ATTRS ( 'Fiscal Period', !Fiscal Period, 'Next Period'), 
    !Company,  !Profit Center, !Trading Partner, !BS Account, 'F00', !Balance Sheet Source ,!mBalance Sheet );

['F99' , 'Outlook'] =>   DB('Balance Sheet', !Scenario, 
      IF ( ELISANC ( 'Fiscal Period', 'Outlook Periods', !Fiscal Period) = 1, ATTRS ( 'Fiscal Period', !Fiscal Period, 'Next Period'), ''), 
    !Company,  !Profit Center, !Trading Partner, !BS Account, 'F00', !Balance Sheet Source ,!mBalance Sheet );

['F99' , 'Plan'] =>   DB('Balance Sheet', !Scenario, 
      IF ( ELISANC ( 'Fiscal Period', 'Outlook Periods', !Fiscal Period) = 1, ATTRS ( 'Fiscal Period', !Fiscal Period, 'Next Period'), ''), 
    !Company,  !Profit Center, !Trading Partner, !BS Account, 'F00', !Balance Sheet Source ,!mBalance Sheet );


['USD', 'TOTACTIVITIES' , 'Outlook', 'Outlook Periods'] => [ 'USD (System)' ] ;
['Local', 'TOTACTIVITIES' , 'Outlook', 'Outlook Periods']=> [ 'Local (System)' ] ;

['USD', 'TOTACTIVITIES' , 'Plan', 'Outlook Periods'] => [ 'USD (System)' ] ;
['Local', 'TOTACTIVITIES' , 'Plan', 'Outlook Periods']=> [ 'Local (System)' ] ;


['All BS Account', 'TOTACTIVITIES', 'USD (System)' , 'Outlook', 'Outlook Periods'] => ['USD', '55000099', 'F16'];
['All BS Account', 'TOTACTIVITIES', 'Local (System)' , 'Outlook', 'Outlook Periods'] => ['Local', '55000099', 'F16'];

['All BS Account', 'TOTACTIVITIES', 'USD (System)' , 'Plan', 'Outlook Periods'] => ['USD', '55000099', 'F16'];
['All BS Account', 'TOTACTIVITIES', 'Local (System)' , 'Plan', 'Outlook Periods'] => ['Local', '55000099', 'F16'];

SKIPCHECK;


#--- Assessment % on Actual Scenario ---#
[ 'Assessment %'] = 
IF ( ELISANC ('PL Account', 'ALLOCATION', !PL ACCOUNT) = 1 % DIMNM ( 'PL Account', DIMIX ( 'PL Account', !PL Account)) @= 'ALLOCATION',
  ['USD'] \ ['USD', 'All Profit Center'],0);



#------------------------------------------------------------
#---- Code to calculate trailing 12 assessment % from outlook
#-- Enable feeder too
#------------------------------------------------------------
# ['Outlook',  'TTM Assessment %'] = N:
#   IF ( !Fiscal Period @= DB ('SYS Control', 'Outlook Start', 'String' ) &
#       !PL Account @=  DB ( 'Below the Line Assessment', !Scenario, !Fiscal Period, !Cost Center, 'Profit Center Undefined', !PL Account, !Below the Line Source, 'Assessment Account' ),


#   DB ('Below the Line Assessment', 'Actual', 'Current Period TTM',  !Cost Center, !Profit Center,  !PL Account, !Below the Line Source
#  , 'Assessment %' ), STET);



['Outlook',  'Effective Assessment %'] = N:

  IF ( ['Outlook', 'Override Assessment %'] <> 0, ['Outlook', 'Override Assessment %'], 
  ['Outlook', 'TTM Assessment %'] );


['Plan',  'Effective Assessment %'] = N:

  IF ( ['Plan', 'Override Assessment %'] <> 0, ['Plan', 'Override Assessment %'], 
  ['Plan', 'TTM Assessment %'] );


['Outlook', 'Override Assessment %'] = 

  IF ( ELISANC ( 'PL Account', 'BTLFULLCST', !PL Account ) = 1,

  DB ( 'Below the Line Assessment', !Scenario, !Fiscal Period, !Cost Center, !Profit Center,
       DB ( 'Below the Line Assessment', !Scenario, !Fiscal Period, !Cost Center, 'Profit Center Undefined', !PL Account, !Below the Line Source, 'Assessment Account'), 
      !Below the Line Source,
      'Override Assessment %'), stet);


['Plan', 'Override Assessment %'] = 

  IF ( ELISANC ( 'PL Account', 'BTLFULLCST', !PL Account ) = 1,

  DB ( 'Below the Line Assessment', !Scenario, !Fiscal Period, !Cost Center, !Profit Center,
       DB ( 'Below the Line Assessment', !Scenario, !Fiscal Period, !Cost Center, 'Profit Center Undefined', !PL Account, !Below the Line Source, 'Assessment Account'), 
      !Below the Line Source,
      'Override Assessment %'), stet);

['Actual', 'Manual PAx Entry', 'Override Assessment %'] = 

  IF ( ELISANC ( 'PL Account', 'BTLFULLCST', !PL Account ) = 1,

  DB ( 'Below the Line Assessment', !Scenario, !Fiscal Period, !Cost Center, !Profit Center,
       DB ( 'Below the Line Assessment', !Scenario, !Fiscal Period, !Cost Center, 'Profit Center Undefined', !PL Account, !Below the Line Source, 'Assessment Account'), 
      !Below the Line Source,
      'Override Assessment %'), stet);

feeders;

['Outlook', 'Allocation' , 'Override Assessment %']  => ['Outlook', 'BTLFULLCST', 'Override Assessment %'];

['Plan', 'Allocation' , 'Override Assessment %']  => ['Plan', 'BTLFULLCST', 'Override Assessment %'];

['USD'] => ['Assessment %'] ;

#------------------------------------------------------------
#---- Code to calculate trailing 12 assessment % from outlook
#-- Enable feeder too
#------------------------------------------------------------

# ['Actual',  'Current Period TTM', 'Assessment %' ] => 
#   DB ( 'Below the Line Assessment', 'Outlook', DB ('SYS Control', 'Outlook Start', 'String' ), !Cost Center, !Profit Center, !PL Account, !Below the Line Source, 'TTM Assessment %');


['Outlook', 'Override Assessment %'] => ['Outlook', 'Effective Assessment %'];
['Outlook',   'TTM Assessment %'] => ['Outlook', 'Effective Assessment %'];


['Plan', 'Override Assessment %'] => ['Plan', 'Effective Assessment %'];
['Plan',   'TTM Assessment %'] => ['Plan', 'Effective Assessment %'];

SKIPCHECK;

['USD'] =N:
 IF ( ATTRS ('Cost Center',!Cost Center, 'Functional Area') @= !Functional Area,
  DB( 'Below the Line', !Scenario, !Fiscal Period, !Cost Center, !PL Account, !Below the Line Source , !mBelow The Line ),
 STET); 

['Local'] =N:
 IF ( ATTRS ('Cost Center',!Cost Center, 'Functional Area') @= !Functional Area,
  DB( 'Below the Line', !Scenario, !Fiscal Period, !Cost Center, !PL Account, !Below the Line Source, !mBelow The Line ),
 STET); 


['Headcount'] =N:
 IF ( ATTRS ('Cost Center',!Cost Center, 'Functional Area') @= !Functional Area,
  DB( 'Below the Line', !Scenario, !Fiscal Period, !Cost Center, !PL Account, !Below the Line Source, !mBelow The Line ),
 STET); 

FEEDERS;

##  UPDATED  07.30.25

SKIPCHECK;

['Escalation $']=N:(['Escalation %']*['BASE']);
['Escalation %']=C:['Escalation $']\['Base'];



FEEDERS;

['Escalation %'] => ['Escalation $'];
['Base'] => ['Escalation $'];

SKIPCHECK;

#--- In current Fiscal Year set period rollups to the current fiscal period (sys control), else set it to the last child
[ {'Headcount', 'FTE'}, 'Actual' ] = C:
  IF ( ELLEV ('Fiscal Period', !Fiscal Period) > 0 &
  SUBST ( !Fiscal Period, 1, 4)  @= DB ( 'SYS Control', 'Current Fiscal Year', 'String' ),
    DB ( 'Corporate Headcount', !Scenario, DB ( 'SYS Control', 'Close Period', 'String' ), !Cost Center, !Pay Group, !Employee Type, !Position, !Employee, !mCorporate Headcount), continue );

[ {'Headcount', 'FTE'}, 'Actual' ] = C:
  IF ( ELLEV ('Fiscal Period', !Fiscal Period) > 0 &
  SUBST ( !Fiscal Period, 1, 4)  @<> DB ( 'SYS Control', 'Current Fiscal Year', 'String' ),
     DB ( 'Corporate Headcount', !Scenario, ELCOMP ( 'Fiscal Period', !Fiscal Period, ELCOMPN ('Fiscal Period', !Fiscal Period)), !Cost Center, !Pay Group, !Employee Type, !Position, !Employee, !mCorporate Headcount)  , stet);



[ {'Headcount', 'FTE'} ] = C:
  IF ( ELLEV ('Fiscal Period', !Fiscal Period) > 0 ,

     DB ( 'Corporate Headcount', !Scenario, ELCOMP ( 'Fiscal Period', !Fiscal Period, ELCOMPN ('Fiscal Period', !Fiscal Period)), !Cost Center, !Pay Group, !Employee Type, !Position, !Employee, !mCorporate Headcount)  , stet


  );


FEEDERS;

SKIPCHECK;

[ {'Actual', 'Outlook'} , 'Below the Line', 'USD'] =N:
 IF ( ATTRS ('Cost Center',!Cost Center, 'Functional Area') @= !Functional Area,
  DB( 'Below the Line', !Scenario, !Fiscal Period, !Cost Center, !PL Account, 'All Sources' , !mCost Center),
 STET); 

[ {'Actual', 'Outlook'} , 'Below the Line', 'Local'] =N:
 IF ( ATTRS ('Cost Center',!Cost Center, 'Functional Area') @= !Functional Area,
  DB( 'Below the Line', !Scenario, !Fiscal Period, !Cost Center, !PL Account, 'All Sources' , !mCost Center),
 STET); 


[ {'Actual', 'Outlook'} , 'Fixed Manufacturing Cost', 'USD'] =N:
 IF ( ATTRS ('Cost Center',!Cost Center, 'Functional Area') @= !Functional Area,
  DB('Fixed Manufacturing Cost', !Scenario, !Fiscal Period, !Cost Center, !PL Account, !mCost Center),
 STET); 

[ {'Actual', 'Outlook'} , 'Fixed Manufacturing Cost', 'Local'] =N:
 IF ( ATTRS ('Cost Center',!Cost Center, 'Functional Area') @= !Functional Area,
  DB('Fixed Manufacturing Cost', !Scenario, !Fiscal Period, !Cost Center, !PL Account, !mCost Center),
 STET); 

FEEDERS;

SKIPCHECK;

['mCost Estimate':'mCost Estimate':'costing_lot_size', 'ELEMENT':'ELEMENT':'All ELEMENT', 'Component':'Component':'All Components'] = C:

  ConsolidatedAvg( 2, 'Cost Estimate', !Currency Type, !Fiscal Period, !Plant, !Profit Center, !Material, !Component, !ELEMENT, !mCost Estimate );


['mCost Estimate':'mCost Estimate':'consumption_qty', 'Component':'Component':'All Components'] = C:0;

FEEDERS;

SKIPCHECK;

['Consumed Dollars']=n:['Consumed Qty']*['Consumed U/C'];
['Consumed U/C']=C:['Consumed Dollars']\['Consumed Qty'];
['Dollars']=n:['receipts']*['Price'];
['Price']=C:['Dollars']\['receipts'];


FEEDERS;


['Consumed Qty'] =>['Consumed Dollars'];

['receipts'] =>['Dollars'];

SKIPCHECK;




FEEDERS;

['Actual', 'USD'] =>
  DB('Cost Center', !Scenario, !Fiscal Period, ATTRS('Cost Center', !Cost Center, 'Functional Area'), !Cost Center, !PL Account, 'Fixed Manufacturing Cost', !mFixed Manufacturing Cost );


['Actual', 'Local'] =>
  DB('Cost Center', !Scenario, !Fiscal Period, ATTRS('Cost Center', !Cost Center, 'Functional Area'), !Cost Center, !PL Account, 'Fixed Manufacturing Cost', !mFixed Manufacturing Cost );


['Outlook', 'USD'] =>
  DB('Cost Center', !Scenario, !Fiscal Period, ATTRS('Cost Center', !Cost Center, 'Functional Area'), !Cost Center, !PL Account, 'Fixed Manufacturing Cost', !mFixed Manufacturing Cost );


['Outlook', 'Local'] =>
  DB('Cost Center', !Scenario, !Fiscal Period, ATTRS('Cost Center', !Cost Center, 'Functional Area'), !Cost Center, !PL Account, 'Fixed Manufacturing Cost', !mFixed Manufacturing Cost );

SKIPCHECK;

['Outlook', 'Override Assessment %'] = 

  IF ( ELISANC ( 'PL Account', 'SENONCASH', !PL Account ) = 1,

  DB ( 'Fixed Manufacturing Cost Assessment', !Scenario, !Fiscal Period, !Cost Center, !Profit Center,
       DB('Fixed Manufacturing Cost Assessment', !Scenario, !Fiscal Period, !Cost Center, 'Profit Center Undefined', !PL Account, !Fixed Manufacturing Cost Assessment Source, 'Assessment Account' ), 
      !Fixed Manufacturing Cost Assessment Source,
      'Override Assessment %'), stet);


FEEDERS;

['Outlook', '67000001' , 'Override Assessment %']  => ['Outlook', 'SENONCASH', 'Override Assessment %'];

SKIPCHECK;

['Beginning Balance'] = N:
  DB ( 'Glenn Springs Project', !Scenario, ATTRS ( 'Fiscal Period', !Fiscal Period, 'Prior Period'), !Vendor, !Glenn Springs Order, 'Current Balance', !Glenn Springs Task, !Glenn Springs Phase, 'USD' );


['Beginning Balance'] = C:
  IF ( ELLEV ('Fiscal Period', !Fiscal Period) <> 0,
  DB ( 'Glenn Springs Project', !Scenario, ELCOMP  ( 'Fiscal Period', !Fiscal Period, 1 ), !Vendor, !Glenn Springs Order, 'Beginning Balance', !Glenn Springs Task, !Glenn Springs Phase, 'USD' ), 
  STET );


['Current Balance'] = C:
  IF ( ELLEV ('Fiscal Period', !Fiscal Period) <> 0,
  DB ( 'Glenn Springs Project', !Scenario, ELCOMP  ( 'Fiscal Period', !Fiscal Period, ELCOMPN('Fiscal Period', !Fiscal Period) ), !Vendor, !Glenn Springs Order, 'Current Balance', !Glenn Springs Task, !Glenn Springs Phase, 'USD' ), 
  STET );

FEEDERS;
['Current Balance', 'USD'] => 
   DB ( 'Glenn Springs Project', !Scenario, ATTRS ( 'Fiscal Period', !Fiscal Period, 'Next Period'), !Vendor, !Glenn Springs Order, 'Current Balance', !Glenn Springs Task, !Glenn Springs Phase, 'USD' );

FEEDSTRINGS;
SKIPCHECK;

['Level'] = S:

  IF ( ['P1'] <> 0,  'P1',Continue);

['Level'] = S:

  IF ( ['P2'] <> 0,  'P2',Continue);

['Level'] = S:

  IF ( ['P3'] <> 0,  'P3',Continue);

['Level'] = S:

  IF ( ['P4'] <> 0,  'P4',Continue);

['Level'] = S:

  IF ( ['P5'] <> 0,  'P5',Continue);

['Level'] = S:

  IF ( ['P6'] <> 0,  'P6',Continue);

['Level'] = S:

  IF ( ['P7'] <> 0,  'P7',Continue);


['Eff Level'] =  S:
  IF ( DB('Intercompany', !Scenario, !Fiscal Period, !Plant, !Functional Area, !Customer, !Ship To, !Profit Center, !Partner Profit Center, !Material, !PL Account, 'Level Override' ) @= 'Ignore',
  '', CONTINUE );

['Eff Level'] =  S:
  IF ( DB('Intercompany', !Scenario, !Fiscal Period, !Plant, !Functional Area, !Customer, !Ship To, !Profit Center, !Partner Profit Center, !Material, !PL Account, 'Level Override' ) @<> '',

 DB('Intercompany', !Scenario, !Fiscal Period, !Plant, !Functional Area, !Customer, !Ship To, !Profit Center, !Partner Profit Center, !Material, !PL Account, 'Level Override' ) ,
  DB('Intercompany', !Scenario, !Fiscal Period, !Plant, !Functional Area, !Customer, !Ship To, !Profit Center, !Partner Profit Center, !Material, !PL Account, 'Level' ) );


# ['Sales Elim Profit Center'] = S:

#   IF ( ['P1'] <> 0, !Profit Center | 'P1',Continue);

# ['Sales Elim Profit Center'] = S:

#   IF ( ['P2'] <> 0, !Profit Center | 'P2',Continue);

# ['Sales Elim Profit Center'] = S:

#   IF ( ['P3'] <> 0, !Profit Center | 'P3',Continue);

# ['Sales Elim Profit Center'] = S:

#   IF ( ['P4'] <> 0, !Profit Center | 'P4',Continue);

# ['Sales Elim Profit Center'] = S:

#   IF ( ['P5'] <> 0, !Profit Center | 'P5',Continue);

# ['Sales Elim Profit Center'] = S:

#   IF ( ['P6'] <> 0, !Profit Center | 'P6',Continue);

# ['Sales Elim Profit Center'] = S:

#   IF ( ['P7'] <> 0, !Profit Center | 'P7',Continue);

['Sales Elim Profit Center'] = S:
  IF ( DB('Intercompany', !Scenario, !Fiscal Period, !Plant, !Functional Area, !Customer, !Ship To, !Profit Center, !Partner Profit Center, !Material, !PL Account, 'Eff Level' ) @<> '' &
       DB('Intercompany', !Scenario, !Fiscal Period, !Plant, !Functional Area, !Customer, !Ship To, !Profit Center, !Partner Profit Center, !Material, !PL Account, 'Sales Elim Profit Center Override' ) @= ''
  ,
  !Profit Center | DB('Intercompany', !Scenario, !Fiscal Period, !Plant, !Functional Area, !Customer, !Ship To, !Profit Center, !Partner Profit Center, !Material, !PL Account, 'Eff Level' ), CONTINUE);

['Sales Elim Profit Center'] = S:
  IF ( DB('Intercompany', !Scenario, !Fiscal Period, !Plant, !Functional Area, !Customer, !Ship To, !Profit Center, !Partner Profit Center, !Material, !PL Account, 'Eff Level' ) @<> '' &
       DB('Intercompany', !Scenario, !Fiscal Period, !Plant, !Functional Area, !Customer, !Ship To, !Profit Center, !Partner Profit Center, !Material, !PL Account, 'Sales Elim Profit Center Override' ) @<> ''
  ,
  DB('Intercompany', !Scenario, !Fiscal Period, !Plant, !Functional Area, !Customer, !Ship To, !Profit Center, !Partner Profit Center, !Material, !PL Account, 'Sales Elim Profit Center Override' ) | 
  DB('Intercompany', !Scenario, !Fiscal Period, !Plant, !Functional Area, !Customer, !Ship To, !Profit Center, !Partner Profit Center, !Material, !PL Account, 'Eff Level' ), STET);

['Sales Elim Account'] = S:

  IF ( DB('Intercompany', !Scenario, !Fiscal Period, !Plant, !Functional Area, !Customer, !Ship To, !Profit Center, !Partner Profit Center, !Material, !PL Account, 'Sales Elim Profit Center' ) @<> '',
   !PLAccount, stet );

['Sales Elim USD'] = N:

 IF ( DB('Intercompany', !Scenario, !Fiscal Period, !Plant, !Functional Area, !Customer, !Ship To, !Profit Center, !Partner Profit Center, !Material, !PL Account, 'Sales Elim Profit Center' ) @<> '' &
      DB('Intercompany', !Scenario, !Fiscal Period, !Plant, !Functional Area, !Customer, !Ship To, !Profit Center, !Partner Profit Center, !Material, !PL Account, 'Sales Elim Account' ) @<> '',
  ['USD'] * -1, stet);


['Sales Elim Reporting Qty'] = N:

 IF ( DB('Intercompany', !Scenario, !Fiscal Period, !Plant, !Functional Area, !Customer, !Ship To, !Profit Center, !Partner Profit Center, !Material, !PL Account, 'Sales Elim Profit Center' ) @<> '' &
      DB('Intercompany', !Scenario, !Fiscal Period, !Plant, !Functional Area, !Customer, !Ship To, !Profit Center, !Partner Profit Center, !Material, !PL Account, 'Sales Elim Account' ) @<> '',
  ['Reporting Qty'] * -1, stet);



# ['COS Elim Profit Center'] = S:

#   IF ( ['P1'] <> 0, !Profit Center | 'P1',Continue);

# ['COS Elim Profit Center'] = S:

#   IF ( ['P2'] <> 0, !Profit Center | 'P2',Continue);

# ['COS Elim Profit Center'] = S:

#   IF ( ['P3'] <> 0, !Profit Center | 'P3',Continue);

# ['COS Elim Profit Center'] = S:

#   IF ( ['P4'] <> 0, !Profit Center | 'P4',Continue);

# ['COS Elim Profit Center'] = S:

#   IF ( ['P5'] <> 0, !Profit Center | 'P5',Continue);

# ['COS Elim Profit Center'] = S:

#   IF ( ['P6'] <> 0, !Profit Center | 'P6',Continue);

# ['COS Elim Profit Center'] = S:

#   IF ( ['P7'] <> 0, !Profit Center | 'P7',Continue);

['COS Elim Profit Center'] = S:
  DB('Intercompany', !Scenario, !Fiscal Period, !Plant, !Functional Area, !Customer, !Ship To, !Profit Center, !Partner Profit Center, !Material, !PL Account, 'Sales Elim Profit Center' ) ;


['COS Elim Account'] = S:

  IF ( DB('Intercompany', !Scenario, !Fiscal Period, !Plant, !Functional Area, !Customer, !Ship To, !Profit Center, !Partner Profit Center, !Material, !PL Account, 'COS Elim Profit Center' ) @<> '' &
   !Profit Center @= '45401000',
   '67300000', CONTINUE);

['COS Elim Account'] = S:

  IF ( DB('Intercompany', !Scenario, !Fiscal Period, !Plant, !Functional Area, !Customer, !Ship To, !Profit Center, !Partner Profit Center, !Material, !PL Account, 'COS Elim Profit Center' ) @<> '' &
  ATTRS ( 'PL Account', !PL Account, 'Sales Area') @= 'IND',

   '65200002', continue );

['COS Elim Account'] = S:

  IF ( DB('Intercompany', !Scenario, !Fiscal Period, !Plant, !Functional Area, !Customer, !Ship To, !Profit Center, !Partner Profit Center, !Material, !PL Account, 'COS Elim Profit Center' ) @<> '' ,

   '65200000', continue );

['COS Elim USD'] = N:

 IF ( DB('Intercompany', !Scenario, !Fiscal Period, !Plant, !Functional Area, !Customer, !Ship To, !Profit Center, !Partner Profit Center, !Material, !PL Account, 'COS Elim Profit Center' ) @<> '' &
      DB('Intercompany', !Scenario, !Fiscal Period, !Plant, !Functional Area, !Customer, !Ship To, !Profit Center, !Partner Profit Center, !Material, !PL Account, 'COS Elim Account' ) @<> '',
  ['USD'] , stet);


['Issue Sales Elim Profit Center'] = S:
  IF ( ISLEAF() = 1  & 
       DB('Intercompany', !Scenario, !Fiscal Period, !Plant, !Functional Area, !Customer, !Ship To, !Profit Center, !Partner Profit Center, !Material, !PL Account, 'Sales Elim Profit Center' )  @<> '' &
       DIMIX ( 'Profit Center', DB('Intercompany', !Scenario, !Fiscal Period, !Plant, !Functional Area, !Customer, !Ship To, !Profit Center, !Partner Profit Center, !Material, !PL Account, 'Sales Elim Profit Center' )) = 0,
    'Y', 
  STET );

